/* One filling assistant over the existing calculation, with a review before writing. */
var modelSpecDraft=null;
function modelSpecTemplates(){return ModelSpecCore.templates(readJSON(ModelSpecCore.TEMPLATE_KEY,{}));}
function modelSpecError(error){const el=$('fill-error');if(el){el.textContent=error.message||String(error);el.focus();}}
function modelSpecDialog(){modelSpecDraft=null;modal('Заполнить из спецификации',`<div class="fill-assistant"><p>Вставьте JSON, полученный по модели SketchUp. Сначала вы увидите материалы и предложения работ; текущий расчёт изменится после нажатия «Добавить выбранное».</p><div class="mini-actions"><button type="button" onclick="modelSpecDownloadPrompt()">Скачать промпт для ChatGPT</button>${state.modelSpecImports?.length?'<button type="button" onclick="modelSpecRestore()">Восстановить предыдущий расчёт</button>':''}</div><div class="field"><label for="fill-json">Спецификация JSON</label><textarea id="fill-json" rows="9" spellcheck="false" placeholder="Вставьте cj-model-spec, версия 1"></textarea></div><div class="field"><label for="fill-file">Или выберите файл JSON (до 8 МБ)</label><input type="file" id="fill-file" accept=".json,application/json" onchange="modelSpecReadFile(event)"></div><p id="fill-error" class="field-error" role="alert" tabindex="-1"></p><div class="mini-actions"><button class="primary" type="button" onclick="modelSpecParse()">Разобрать спецификацию</button><button type="button" onclick="$('modal').close()">Отмена</button></div></div>`);}
async function modelSpecDownloadPrompt(){try{const response=await fetch('model-spec-prompt.json');if(!response.ok)throw Error('Промпт недоступен');const data=await response.json();download('SketchUp — промпт спецификации.txt',data.text,'text/plain;charset=utf-8');}catch(e){modelSpecError(e);}}
async function modelSpecReadFile(e){try{const f=e.target.files[0];if(!f)return;if(f.size>ModelSpecCore.MAX_BYTES)throw Error('Файл больше 8 МБ');$('fill-json').value=await f.text();modelSpecParse();}catch(err){modelSpecError(err);}}
function modelSpecParse(){try{const raw=$('fill-json').value,spec=ModelSpecCore.parse(raw);if(!spec.products.length)throw Error('В спецификации нет изделий. Уточните доступ к модели и выполните промпт повторно.');modelSpecDraft={spec,raw,productId:spec.products[0].id,profile:'spec',templateId:'',qty:spec.products[0].batch_qty??'',useCard:state.lines.length===0,items:[]};modelSpecBuild();modelSpecPreview();}catch(e){modelSpecError(e);}}
function modelSpecBuild(){const d=modelSpecDraft,t=d.templateId?modelSpecTemplates()[d.templateId]:null;d.items=ModelSpecCore.rows(d.spec,d.productId,d.profile).map(row=>({row,config:ModelSpecCore.config(row,CATALOG,t)}));}
function modelSpecChoose(key,value){try{const d=modelSpecDraft;d[key]=value;if(key==='templateId'&&value)d.profile=modelSpecTemplates()[value].profile;if(key==='productId')d.qty=d.spec.products.find(p=>p.id===value).batch_qty??'';modelSpecBuild();modelSpecPreview();}catch(e){modelSpecError(e);}}
function modelSpecBack(){const raw=modelSpecDraft.raw;modelSpecDialog();$('fill-json').value=raw;}
function modelSpecOptions(index,query=''){const {row,config:c}=modelSpecDraft.items[index],searchRow=query?{...row,name:query}:row;const choices=ModelSpecCore.candidates(searchRow,CATALOG),selected=CATALOG.find(x=>x.id===c.catalogId&&x.kind===row.kind);if(selected&&!choices.some(x=>x.id===selected.id))choices.unshift(selected);return '<option value="">Своя позиция · цена не задана</option>'+choices.map(x=>`<option value="${esc(x.id)}" ${c.catalogId===x.id?'selected':''}>${esc(x.name)} · ${money(x.price)} / ${esc(MaterialCore.unitLabel(x.unit))}</option>`).join('');}
function modelSpecSearch(i,value){$('fill-catalog-'+i).innerHTML=modelSpecOptions(i,value);}
function modelSpecChange(i,key,value){try{const entry=modelSpecDraft.items[i],c=entry.config;c[key]=value;if(key==='catalogId'){const catalog=CATALOG.find(x=>x.id===value&&x.kind===entry.row.kind),next=ModelSpecCore.config(entry.row,catalog?[catalog]:[],null);Object.assign(c,{catalogId:catalog?.id||'',name:catalog?.name||entry.row.name,unit:next.unit,driver:next.driver,factor:null,note:'',manual:null});modelSpecPreview();const details=$('fill-row-'+i)?.querySelector('details');if(details)details.open=true;$('fill-driver-'+i)?.focus();return;}if(key==='unit'){c.factor=null;c.note='';$('fill-factor-'+i).value='';$('fill-note-'+i).value='';}if(key==='inclusion'&&value!=='separate'){c.selected=false;$('fill-select-'+i).checked=false;}modelSpecRefresh();}catch(e){modelSpecError(e);}}
function modelSpecNumber(value){return value===''?null:Number(value);}
function modelSpecRow(entry,i){const {row,config:c}=entry,tool=['tool','equipment'].includes(row.role),label=tool?'Инструмент / оборудование':row.type==='part'?'Деталь / комплектующее':row.type==='work'?'Работа':'Расходник / комплектующее';
 if(tool)return `<article class="fill-row fill-tool"><b>${esc(row.name)}</b><p class="small">${label}: проверьте наличие и обеспечение. Покупка автоматически не начисляется.</p></article>`;
 const driver=ModelSpecCore.drive(modelSpecDraft.spec,row,c.driver);return `<article class="fill-row" id="fill-row-${i}"><div class="fill-row-head"><label class="checkrow" for="fill-select-${i}"><input id="fill-select-${i}" type="checkbox" ${c.selected?'checked':''} ${row.disabled?'disabled':''} onchange="modelSpecChange(${i},'selected',this.checked)"><span><b>${esc(row.name)}</b><span class="source">${label}${row.entity.status==='inferred'?' · предложение':''}${row.entity.alternative_group?' · вариант '+esc(row.entity.alternative_group):''}</span></span></label><output id="fill-result-${i}" class="fill-result"></output></div>${row.disabled?'<p class="small">Исключено из добавления: ресурс включён в ставку либо способ поставки узла требует уточнения. Проверьте состав спецификации.</p>':''}<p class="small" id="fill-reason-${i}"></p><details><summary>Подобрать позицию и настроить объём</summary><div class="field"><label for="fill-search-${i}">Поиск в справочнике</label><input id="fill-search-${i}" type="search" placeholder="Название, марка, размер" oninput="modelSpecSearch(${i},this.value)"></div><div class="field"><label for="fill-catalog-${i}">Позиция и ставка — проверьте технические параметры</label><select id="fill-catalog-${i}" onchange="modelSpecChange(${i},'catalogId',this.value)">${modelSpecOptions(i)}</select></div><div class="grid2"><div class="field"><label for="fill-name-${i}">Название своей позиции</label><input id="fill-name-${i}" value="${esc(c.name)}" ${c.catalogId?'disabled':''} oninput="modelSpecChange(${i},'name',this.value)"></div><div class="field"><label for="fill-unit-${i}">Единица позиции</label><input id="fill-unit-${i}" value="${esc(MaterialCore.unitLabel(c.unit))}" ${c.catalogId?'disabled':''} oninput="modelSpecChange(${i},'unit',this.value)" placeholder="н/ч, л, кг, м²…"></div></div><div class="field"><label for="fill-driver-${i}">От чего считать объём</label><select id="fill-driver-${i}" onchange="modelSpecChange(${i},'driver',this.value)">${Object.entries(ModelSpecCore.METRICS).map(([key,[name]])=>{const v=ModelSpecCore.drive(modelSpecDraft.spec,row,key);return `<option value="${key}" ${c.driver===key?'selected':''}>${name} · ${dec(v.value)} ${esc(v.unit||'')} / ${v.basis==='batch'?'партия':'изделие'}</option>`;}).join('')}</select></div><div class="grid2"><div class="field"><label for="fill-factor-${i}">Норма: единиц позиции на единицу выбранного объёма</label><input id="fill-factor-${i}" type="number" min="0" step="any" value="${c.factor??''}" oninput="modelSpecChange(${i},'factor',modelSpecNumber(this.value))"></div><div class="field"><label for="fill-note-${i}">Основание нормы (включите слои и потери явно)</label><input id="fill-note-${i}" value="${esc(c.note)}" oninput="modelSpecChange(${i},'note',this.value)"></div></div><label class="checkrow"><input type="checkbox" ${c.estimate?'checked':''} onchange="modelSpecChange(${i},'estimate',this.checked)">Норма предварительная</label>${row.type==='resource'?`<div class="field"><label for="fill-inclusion-${i}">Ресурс в стоимости работы</label><select id="fill-inclusion-${i}" onchange="modelSpecChange(${i},'inclusion',this.value)">${[['unknown','Нужно уточнить'],['separate','Учитывается отдельно'],['included','Уже включён в ставку']].map(([v,n])=>`<option value="${v}" ${c.inclusion===v?'selected':''}>${n}</option>`).join('')}</select></div>`:''}<div class="field"><label id="fill-manual-label-${i}" for="fill-manual-${i}">Или объём вручную (${driver.basis==='batch'?'на всю партию':'на одно изделие'})</label><input id="fill-manual-${i}" type="number" min="0" step="any" value="${c.manual??''}" oninput="modelSpecChange(${i},'manual',modelSpecNumber(this.value))"><p class="hint">Ручной объём имеет приоритет и не сохраняется в шаблоне. Неизвестное можно оставить пустым.</p></div></details></article>`;
}
function modelSpecPreview(){const d=modelSpecDraft,templates=modelSpecTemplates(),product=d.spec.products.find(p=>p.id===d.productId);$('modalBody').innerHTML=`<div class="fill-assistant"><p>Проверьте подбор и отметьте нужные работы. Нормы и цены без источника остаются неизвестными. Выбранные строки добавятся к текущему расчёту.</p><div class="grid2"><div class="field"><label for="fill-product">Изделие из спецификации</label><select id="fill-product" onchange="modelSpecChoose('productId',this.value)">${d.spec.products.map(p=>`<option value="${p.id}" ${p.id===d.productId?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label for="fill-profile">Предложить процессы</label><select id="fill-profile" onchange="modelSpecChoose('profile',this.value)">${[['spec','По спецификации'],['wood','Дерево: раскрой, шлифовка, покрытие'],['steel','Стальной каркас: раскрой, сварка, покрытие']].map(([v,n])=>`<option value="${v}" ${v===d.profile?'selected':''}>${n}</option>`).join('')}</select></div></div><label class="checkrow"><input id="fill-use-card" type="checkbox" ${d.useCard?'checked':''} onchange="modelSpecDraft.useCard=this.checked">Использовать название «${esc(product.name)}» и тираж ниже</label><div class="field"><label for="fill-qty">Тираж выбранного изделия</label><input id="fill-qty" type="number" min="1" step="1" value="${esc(d.qty)}" oninput="modelSpecDraft.qty=this.value"><p class="hint">Если флажок снят, сохранятся название и тираж текущего расчёта: ${state.qty} шт. Смена профиля или шаблона заново формирует предложения.</p></div><details class="fill-template"><summary>Мои шаблоны заполнения</summary><div class="field"><label for="fill-template">Применить сохранённые нормы и подбор</label><select id="fill-template" onchange="modelSpecChoose('templateId',this.value)"><option value="">Без сохранённого шаблона</option>${Object.values(templates).map(t=>`<option value="${t.id}" ${t.id===d.templateId?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div><p class="small">Шаблон переносит выбор работ, позиции и нормы для совпавших названий/типов процессов. Проверьте применимость к новому изделию; ручные объёмы не переносятся. Для повторения набора включите тот же профиль процессов.</p><div class="field"><label for="fill-template-name">Название нового шаблона</label><input id="fill-template-name" maxlength="200" placeholder="Например: наш сварной каркас"></div><button type="button" onclick="modelSpecSaveTemplate()">Сохранить настройки новым шаблоном</button><p id="fill-template-status" role="status"></p></details><p id="fill-error" class="field-error" role="alert" tabindex="-1"></p><div id="fill-rows">${d.items.map(modelSpecRow).join('')}</div><details class="fill-source"><summary>Источник, ограничения и вопросы (${d.spec.questions.length})</summary><p>${esc(d.spec.source.model_name||'Модель не названа')} · ${esc(d.spec.source.revision||'ревизия не задана')}</p><p class="small">${esc(d.spec.source.scope||'Границы не заданы')} · ${d.spec.source.completeness==='complete_within_scope'?'Состав в выбранных границах исследован':'Спецификация неполная'}</p>${[...d.spec.source.limitations,...d.spec.questions.map(q=>q.text)].map(n=>`<p class="small">${esc(n)}</p>`).join('')}</details><div class="fill-actions"><p id="fill-summary" role="status" aria-live="polite"></p><div class="mini-actions"><button class="primary" id="fill-apply" type="button" onclick="modelSpecCommit()">Добавить выбранное</button><button type="button" onclick="modelSpecBack()">Назад к JSON</button><button type="button" onclick="$('modal').close()">Отмена</button></div></div></div>`;modelSpecRefresh();}
function modelSpecRefresh(){let selected=0,unknown=0;modelSpecDraft.items.forEach(({row,config:c},i)=>{if(['tool','equipment'].includes(row.role))return;let result;try{result=ModelSpecCore.amount(modelSpecDraft.spec,row,c);}catch(e){result={value:null,note:e.message};}const scope=result.scope==='batch'?'партия':'изделие',out=$('fill-result-'+i);out.textContent=result.value===null?'Нужно уточнить':dec(result.value)+' '+c.unit+' / '+scope;out.classList.toggle('fill-pending',result.value===null);const target=CATALOG.find(x=>x.id===c.catalogId);$('fill-manual-label-'+i).textContent='Или объём вручную ('+(scope==='партия'?'на всю партию':'на одно изделие')+')';$('fill-reason-'+i).textContent=(target?'Подобрано: '+target.name+' · '+money(target.price)+' / '+target.unit+'. ':'')+(result.preliminary?'Предварительно · ':'')+result.note+(c.catalogId?'':' · цена своей позиции не задана')+(row.type==='resource'&&c.inclusion==='unknown'?' · уточните включение в ставку':'');if(c.selected&&!row.disabled){selected++;if(result.value===null)unknown++;}});$('fill-summary').textContent='Выбрано строк: '+selected+' · с неизвестным объёмом: '+unknown+'. Цена и комплектность требуют проверки.';$('fill-apply').disabled=!selected;}
function modelSpecSaveTemplate(){try{const name=$('fill-template-name').value.trim(),rules=new Map();for(const {row,config:c} of modelSpecDraft.items){if(row.disabled)continue;const r={key:row.templateKey,catalogId:c.catalogId,unit:c.unit,driver:c.driver,factor:c.factor,note:c.note,estimate:c.estimate,inclusion:c.inclusion,selected:c.selected};if(rules.has(r.key)&&JSON.stringify(rules.get(r.key))!==JSON.stringify(r))throw Error('Для одинаковых процессов заданы разные нормы. Уточните названия в спецификации.');rules.set(r.key,r);}const t=ModelSpecCore.template({version:1,id:uid(),name,profile:modelSpecDraft.profile,rules:[...rules.values()]}),all=ModelSpecCore.templates({...modelSpecTemplates(),[t.id]:t});if(!writeJSON(ModelSpecCore.TEMPLATE_KEY,all))throw Error('Шаблон не сохранён');$('fill-template-status').textContent='Шаблон «'+name+'» сохранён. Он доступен в следующем заполнении.';const option=document.createElement('option');option.value=t.id;option.textContent=t.name;$('fill-template').append(option);}catch(e){modelSpecError(e);}}
function modelSpecCommit(){try{const d=modelSpecDraft;if(state.engineVersion&&!(CostEngine.SUPPORTED_VERSIONS||[CostEngine.VERSION]).includes(state.engineVersion))throw Error('Неизвестная методика: создайте отдельный расчёт');const result=ModelSpecCore.apply(state,d.spec,d.productId,d.items,(catalogId,kind)=>{const catalog=CATALOG.find(c=>c.id===catalogId&&c.kind===kind);if(catalogId&&!catalog)throw Error('Позиция справочника не найдена');const line=lineFrom(catalog);line.kind=kind;return line;});if(d.useCard){const qty=Number(d.qty);if(!Number.isInteger(qty)||qty<1)throw Error('Укажите целый положительный тираж либо снимите обновление карточки заказа');result.state.qty=qty;result.state.name=d.spec.products.find(p=>p.id===d.productId).name;}result.state.updated=stamp();DomainSchema.calculation(result.state);ModelSpecCore.saveWithRecovery(localStorage,result.state,state);state=result.state;window.draftSaveFailed=false;$('modal').close();modelSpecDraft=null;go(1);toast('Добавлено строк: '+result.added+'. Предыдущий расчёт сохранён для восстановления.');}catch(e){modelSpecError(e);}}
function modelSpecRestore(){try{const old=readJSON('izdelie-recovery',null);if(!validState(old))throw Error('Восстановительная копия недоступна');ModelSpecCore.saveWithRecovery(localStorage,old,state);state=old;window.draftSaveFailed=false;$('modal').close();modelSpecDraft=null;go(1);toast('Предыдущий расчёт восстановлен');}catch(e){modelSpecError(e);}}
(function(){
 const previousClean=cleanCalculation;cleanCalculation=function(s){const c=previousClean(s);if(s.modelSpecImports!==undefined)c.modelSpecImports=structuredClone(s.modelSpecImports);c.lines.forEach((l,i)=>{if(s.lines[i].modelSpecOrigin!==undefined)l.modelSpecOrigin=structuredClone(s.lines[i].modelSpecOrigin);});if(s.archive&&s.archive.signature===CalculationArchive.signature(s)){c.archive=structuredClone(s.archive);c.archive.signature=CalculationArchive.signature(c);}return c;};
 const previousRender=render;render=function(){previousRender();if(![0,1,2].includes(page)||!document.querySelector)return;const first=$('app').querySelector('.steps')||$('app').querySelector('.page-title');if(!first)return;first.insertAdjacentHTML('afterend','<div class="toolbar fill-entry"><button type="button" onclick="modelSpecDialog()">Заполнить из спецификации</button><span class="small">Материалы, работы и нормы — с предпросмотром</span></div>');if(state.modelSpecImports?.length)$('app').insertAdjacentHTML('beforeend','<details class="card"><summary>Данные из спецификации и оставшиеся вопросы</summary>'+state.modelSpecImports.map(x=>'<p><b>'+esc(x.name)+'</b> · '+esc(x.revision||'без ревизии')+'</p>'+x.notices.map(n=>'<p class="small">'+esc(n)+'</p>').join('')).join('')+'</details>');};render();
})();
